"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
type Request={id:string;custody:string;transit:string;bankAccount:string};
type Props={scope:HandoffScope;bank:string;disabled?:boolean;onSaved:()=>void};
export function CashierLedgerMappingCreate(props:Props){return <MappingForm key={[props.scope.tenant,props.scope.property,props.scope.actor,props.bank].join(':')} {...props}/>}
function MappingForm({scope,bank,disabled=false,onSaved}:Props){
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[choices,setChoices]=useState(['','','']),[confirmed,setConfirmed]=useState(false),[pending,setPending]=useState<Request|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const lock=useRef(false),alive=useRef(false);
 const key=['irp-bank-ledger-setup',scope.tenant,scope.property,scope.actor,bank].join(':');
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const r=JSON.parse(raw);if(![r.id,r.custody,r.transit,r.bankAccount].every(v=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v))||new Set([r.custody,r.transit,r.bankAccount]).size!==3)throw Error('Saved setup request is invalid.');setPending(r);}}catch(e){setError(e instanceof Error?e.message:'Unable to recover setup.');}return()=>{alive.current=false}},[key]);
 async function auth(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen bank accounting.');}
 async function run(save=false){if(lock.current||disabled)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await auth();if(!save){if(pending)return;const result=readAccountingSetup(await hotelRpc('gl_setup',{p_tenant:scope.tenant,p_property:scope.property}),scope.tenant,scope.property);await auth();if(alive.current){setSetup(result);setChoices(['','','']);setConfirmed(false)}}else{
 let r=pending;if(!r){if(!confirmed||new Set(choices).size!==3||choices.some(id=>!setup?.accounts.some(a=>a.account_id===id&&a.active&&a.kind==='asset')))throw Error('Choose three distinct active asset accounts and confirm.');if(sessionStorage.getItem(key)!==null)throw Error('An unresolved setup request already exists. Reopen bank accounting to recover it.');r={id:crypto.randomUUID(),custody:choices[0],transit:choices[1],bankAccount:choices[2]};sessionStorage.setItem(key,JSON.stringify(r));setPending(r);}
 const result=await hotelRpc<Record<string,unknown>>('configure_cashier_bank_ledger',{p_tenant:scope.tenant,p_property:scope.property,p_request:r.id,p_bank:bank,p_custody:r.custody,p_transit:r.transit,p_bank_account:r.bankAccount,p_confirmed:true});await auth();if(result.schema_version!==1||result.tenant_id!==scope.tenant||result.property_id!==scope.property||result.actor_id!==scope.actor||result.id!==r.id||result.bank_id!==bank||result.custody_account!==r.custody||result.transit_account!==r.transit||result.bank_account!==r.bankAccount||result.journal_posted!==false)throw Error('Setup receipt does not match. Retry the saved request.');sessionStorage.removeItem(key);if(alive.current){setPending(null);setConfirmed(false);setMessage('Bank accounting configuration saved. Load ledger accounts to select it.');onSaved();}
 }}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to save bank accounting.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <details><summary>Configure bank accounting</summary><p>Choose separate accounts for cash on hand, deposits travelling to the bank, and the bank balance. Saving this configuration does not post a journal.</p><fieldset disabled={busy||disabled||!!pending}><button type="button" onClick={()=>void run()}>Load available asset accounts</button>{setup&&['Cash on hand','Deposits in transit','Bank balance'].map((label,index)=><label key={label}>{label}<select value={choices[index]} onChange={e=>{setChoices(v=>v.map((id,i)=>i===index?e.target.value:id));setConfirmed(false)}}><option value="">Choose an account</option>{setup.accounts.filter(a=>a.active&&a.kind==='asset').map(a=><option key={a.account_id} value={a.account_id}>{a.code} {a.name}</option>)}</select></label>)}<label><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I confirm these accounting accounts</label></fieldset>{pending&&<p>A saved request needs confirmation. Retrying uses the same request.</p>}<button type="button" disabled={busy||disabled||(!pending&&(!confirmed||choices.includes('')||new Set(choices).size!==3))} onClick={()=>void run(true)}>{pending?'Retry saved configuration':'Save bank accounting'}</button>{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</details>
}
